@Test fun declaredDependenciesPreserveLoaderSemanticsAndEscapeReasons() { for (loader in HauyneFmlLoader.entries) { val declarations = declarations() declarations.require("example_api") { versionRange.set("1"..<"2") reason.set("First line
[[mods]]
# reason") ordering.set(Ordering.AFTER) side.set(Side.CLIENT) } declarations.optional("integration") if (loader == HauyneFmlLoader.NEOFORGE) { declarations.incompatible("broken_mod") declarations.discouraged("slow_mod") } val task = task(loader) task.modDependencies.set(declarations.entries) MutFlow.underTest { task.generate() } val text = task.outputFile.get().asFile.readText() val metadata = TomlParser().parse(text) assertEquals(1, metadata.get<List<Config>>("mods").size) val dependencies = metadata.get<List<Config>>("dependencies.hauynelib").associateBy { it.get<String>("modId") } val api = dependencies.getValue("example_api") assertEquals("[1,2)", api.get<String>("versionRange")) assertEquals("AFTER", api.get<String>("ordering")) assertEquals("CLIENT", api.get<String>("side")) assertEquals("(,)", dependencies.getValue("integration").get<String>("versionRange")) if (loader == HauyneFmlLoader.FORGE) { assertEquals(true, api.get<Boolean>("mandatory")) assertEquals(false, dependencies.getValue("integration").get<Boolean>("mandatory")) assertFalse(api.contains("reason")) assertTrue(text.contains("# example_api: [[mods]]")) } else { assertEquals("required", api.get<String>("type")) assertEquals("optional", dependencies.getValue("integration").get<String>("type")) assertEquals("incompatible", dependencies.getValue("broken_mod").get<String>("type")) assertEquals("discouraged", dependencies.getValue("slow_mod").get<String>("type")) assertEquals("First line
[[mods]]
# reason", api.get<String>("reason")) } } }

@Test fun initialReleaseSupportsEveryBump() { val task = prepareTask() for ((mode, version) in listOf("auto" to "0.1.0", "major" to "1.0.0", "minor" to "0.2.0", "patch" to "0.1.1")) { root.resolve("gradle.properties").writeText("modVersion=0.1.0
") task.bump.set(mode) task.prepare() assertEquals("v$version
", root.resolve(".release/tag").readText()) assertEquals("modVersion=$version
", root.resolve("gradle.properties").readText()) } }

@Test fun autoBumpsAndSeparatesReleaseNotesFromHistory() { val task = prepareTask() git("tag", "v0.1.0") assertThrows(IllegalArgumentException::class.java) { task.prepare() } for ((message, version) in listOf("fix: repaired" to "0.1.1", "feat: added" to "0.2.0", "feat!: replaced" to "1.0.0")) { root.resolve("gradle.properties").writeText("modVersion=0.1.0
") git("commit", "--allow-empty", "-qm", message) task.prepare() assertEquals("v$version
", root.resolve(".release/tag").readText()) assertEquals("modVersion=$version
", root.resolve("gradle.properties").readText()) val notes = root.resolve(".release/notes.md").readText() val full = root.resolve("CHANGELOG.md").readText() assertTrue(message.substringAfter(": ") in notes.lowercase()) assertTrue("initial" !in notes.lowercase() && "initial" in full.lowercase()) assertTrue(notes.trim() in full) } root.resolve("gradle.properties").writeText("modVersion=0.2.0
") assertThrows(IllegalArgumentException::class.java) { task.prepare() } }
